WITH SessionTotals AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) event_type_values, AVG(duration_sec) avg_duration_sec FROM web_events WHERE page NOT IN ('/product', '/search', '/cart') GROUP BY session_id) SELECT s.id, s.started_at, S.event_type_values, S.avg_duration_sec FROM sessions s INNER JOIN SessionTotals S ON s.id = S.session_id WHERE S.avg_duration_sec >= 200
